function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + 2 * Math.floor(rand() * 5);
  const options = size === 'large' ? [1, 7, 600, 1000, 1001, 1500, 2000] : [1, 2, 3, 4, 6, 10];
  const kinds = Math.min(n, options[Math.floor(rand() * options.length)]);
  const span = size === 'large' ? 100000 : 5 + Math.floor(rand() * 10);
  const pool = new Set();
  while (pool.size < Math.min(kinds, 2 * span + 1)) pool.add(Math.floor(rand() * (2 * span + 1)) - span);
  const values = [...pool];
  const candyType = [];
  for (let i = 0; i < n; i++) candyType.push(i < values.length ? values[i] : values[Math.floor(rand() * values.length)]);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [candyType[i], candyType[j]] = [candyType[j], candyType[i]];
  }
  return [candyType];
}
